    def reaches(start, target):
        stack = [start]
        seen = set()
        while stack:
            node = stack.pop()
            if node == target:
                return True
            if node not in seen:
                seen.add(node)
                stack.extend(data[node])
        return False
    out = {}
    for node, parents in data.items():
        unique = sorted(set(parents))
        result = []
        for p in unique:
            # Удаляем p, если существует другой предшественник q такой, что reaches(q, p)
            is_redundant = False
            for q in unique:
                if q != p and reaches(q, p):
                    is_redundant = True
                    break
            if not is_redundant:
                result.append(p)
        out[node] = result
    return out
